public class JUnit5Basics {
    static class StringUtils {
        static boolean isPalindrome(String s) {
            String reversed = new StringBuilder(s).reverse().toString();
            return s.equals(reversed);
        }
    }
    public static void main(String[] args) {
        // Demonstrate — in real code these would be JUnit @Test methods
        System.out.println(StringUtils.isPalindrome("racecar")); // true
        System.out.println(StringUtils.isPalindrome("hello"));   // false
        System.out.println(StringUtils.isPalindrome("level"));   // true
    }
}

