public class MockitoAndTDD {
    interface SpellRepo {
        String findSpell(String name);
    }
    static class MockSpellRepo implements SpellRepo {
        public String findSpell(String name) {
            return name.equals("Fireball") ? "Fireball (80 dmg)" : "Unknown spell";
        }
    }
    static class SpellService {
        private SpellRepo repo;
        SpellService(SpellRepo repo) { this.repo = repo; }
        String getSpellInfo(String name) { return repo.findSpell(name); }
    }
    public static void main(String[] args) {
        SpellService svc = new SpellService(new MockSpellRepo());
        System.out.println(svc.getSpellInfo("Fireball"));
        System.out.println(svc.getSpellInfo("IceBolt"));
    }
}

