public class BDDTesting {
    static class Wizard {
        private int mana;
        Wizard(int mana) { this.mana = mana; }
        int getMana() { return mana; }
        boolean castSpell(int cost) {
            if (cost > mana) return false;
            mana -= cost;
            return true;
        }
    }
    public static void main(String[] args) {
        // Given: wizard with 100 mana, When: cast 40-cost spell, Then: success + 60 mana
        Wizard w1 = new Wizard(100);
        boolean r1 = w1.castSpell(40);
        System.out.println(r1);         // true
        System.out.println(w1.getMana()); // 60

        // Given: wizard with 20 mana, When: cast 40-cost spell, Then: fail + mana unchanged
        Wizard w2 = new Wizard(20);
        boolean r2 = w2.castSpell(40);
        System.out.println(r2);         // false
        System.out.println(w2.getMana()); // 20
    }
}
